8	export async function all_rows_have_region(ctx: AssertionContext): Promise<AssertionResult> {
9	  const total = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.events");
10	  const withRegion = await queryRows<{ n: number }>(
11	    ctx,
12	    "SELECT count() AS n FROM analytics.events WHERE region != '' AND region IS NOT NULL",
13	  );
14	  const totalCount = Number(total[0]?.n ?? 0);
15	  const regionCount = Number(withRegion[0]?.n ?? 0);
16	  const passed = totalCount > 0 && regionCount === totalCount;
17	  return {
18	    passed,
19	    message: passed ? "All rows have region." : `${regionCount}/${totalCount} rows have region.`,
20	    details: { totalCount, regionCount },
21	  };
22	}
